function sigmoid(z: number): number {
  return 1 / (1 + Math.exp(-z));
}

function median(nums: number[]): number {
  const s = [...nums].sort((a, b) => a - b);
  const mid = Math.floor(s.length / 2);
  return s.length % 2 ? s[mid] : (s[mid - 1] + s[mid]) / 2;
}

function rocAuc(scores: number[], labels: number[]): number {
  const pos = scores.filter((_, i) => labels[i] === 1);
  const neg = scores.filter((_, i) => labels[i] === 0);
  let wins = 0, ties = 0;
  for (const p of pos) for (const n of neg) {
    if (p > n) wins += 1;
    else if (p === n) ties += 0.5;
  }
  return wins + ties > 0 ? (wins + ties) / (pos.length * neg.length) : 0.5;
}

function rocCurve(scores: number[], labels: number[]): Array<{ fpr: number; tpr: number }> {
  const sorted = scores
    .map((s, i) => ({ s, y: labels[i] }))
    .sort((a, b) => b.s - a.s);
  const P = labels.filter(y => y === 1).length;
  const N = labels.length - P;
  let tp = 0, fp = 0;
  const pts: Array<{ fpr: number; tpr: number }> = [{ fpr: 0, tpr: 0 }];
  let prev = NaN;
  for (const { s, y } of sorted) {
    if (s !== prev) {
      pts.push({ fpr: fp / N, tpr: tp / P });
      prev = s;
    }
    if (y === 1) tp += 1; else fp += 1;
  }
  pts.push({ fpr: 1, tpr: 1 });
  return pts;
}

Deno.serve(async (req: Request) => {
  if (req.method === 'OPTIONS') {
    return new Response(null, { status: 200, headers: corsHeaders });
  }

  try {
    const supabase = createClient(
      Deno.env.get('SUPABASE_URL')!,
      Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,
    );

    const url = new URL(req.url);

    // POST /ml-model/train — train + evaluate + save artifact
    if (req.method === 'POST' && url.pathname.endsWith('/train')) {
      // Preprocessing: dataset already numeric-coded; clean missing values (none '?'
      // remain in this embedded extract), impute missing with column medians.
      const cols = FEATURE_NAMES.length;
      const medians: number[] = [];
      for (let c = 0; c < cols; c++) {
        const vals = DATASET.map(r => r[c]).filter(v => Number.isFinite(v));
        medians.push(median(vals));
      }
      const cleaned = DATASET.map(r => r.map((v, c) => Number.isFinite(v) ? v : medians[c]));

      // Shuffle + 80/20 train/test split (fixed seed for reproducibility)
      const idx = cleaned.map((_, i) => i);
      let seed = 42;
      const rand = () => { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; };
      for (let i = idx.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [idx[i], idx[j]] = [idx[j], idx[i]];
      }
      const nTrain = Math.round(cleaned.length * 0.8);
      const train = idx.slice(0, nTrain).map(i => cleaned[i]);
      const test = idx.slice(nTrain).map(i => cleaned[i]);

      const Xtr = train.map(r => r.slice(0, cols));
      const ytr = train.map(r => r[13]);
      const Xte = test.map(r => r.slice(0, cols));
      const yte = test.map(r => r[13]);

      // Feature scaling (standardization) fit on train only
      const means = FEATURE_NAMES.map((_, c) => Xtr.reduce((s, r) => s + r[c], 0) / Xtr.length);
      const stds = FEATURE_NAMES.map((_, c) => {
        const m = means[c];
        return Math.sqrt(Xtr.reduce((s, r) => s + (r[c] - m) ** 2, 0) / Xtr.length) || 1;
      });
      const scaleX = (row: number[]) => row.map((v, c) => (v - means[c]) / stds[c]);

      // Logistic regression via gradient descent
      const w = new Array(cols).fill(0);
      let b = 0;
      const lr = 0.05;
      for (let epoch = 0; epoch < 3000; epoch++) {
        const gw = new Array(cols).fill(0);
        let gb = 0;
        for (let i = 0; i < Xtr.length; i++) {
          const z = b + scaleX(Xtr[i]).reduce((s, v, c) => s + v * w[c], 0);
          const err = sigmoid(z) - ytr[i];
          for (let c = 0; c < cols; c++) gw[c] += err * scaleX(Xtr[i])[c];
          gb += err;
        }
        for (let c = 0; c < cols; c++) w[c] -= lr * gw[c] / Xtr.length;
        b -= lr * gb / Xtr.length;
      }

      const predictScore = (row: number[]) => sigmoid(b + scaleX(row).reduce((s, v, c) => s + v * w[c], 0));

      // Evaluation on test set
      const scores = Xte.map(predictScore);
      const preds = scores.map(s => s >= 0.5 ? 1 : 0);
      let tp = 0, fp = 0, tn = 0, fn = 0;
      preds.forEach((p, i) => {
        if (p === 1 && yte[i] === 1) tp++;
        else if (p === 1 && yte[i] === 0) fp++;
        else if (p === 0 && yte[i] === 0) tn++;
        else fn++;
      });
      const accuracy = (tp + tn) / preds.length;
      const precision = tp + fp > 0 ? tp / (tp + fp) : 0;
      const recall = tp + fn > 0 ? tp / (tp + fn) : 0;
      const f1 = precision + recall > 0 ? 2 * precision * recall / (precision + recall) : 0;
      const auc = rocAuc(scores, yte);
      const curve = rocCurve(scores, yte);

      const metrics = {
        accuracy, precision, recall, f1,
        rocAuc: auc,
        confusionMatrix: { tp, fp, tn, fn },
        rocCurve: curve,
      };

      // Save artifact
      const version = `lr-${new Date().toISOString().slice(0, 19).replace(/[:T-]/g, '')}`;
      const { error: saveErr } = await supabase.from('model_artifacts').upsert({
        version,
        algorithm: 'Logistic Regression',
        dataset: 'UCI Heart Disease (Cleveland, 303 samples)',
        feature_names: FEATURE_NAMES,
        means, stds, weights: w, bias: b,
        metrics,
        train_samples: Xtr.length,
        test_samples: Xte.length,
        total_samples: cleaned.length,
      });

      if (saveErr) {
        return new Response(JSON.stringify({ error: 'Failed to save model artifact' }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      return new Response(JSON.stringify({ version, metrics, trainSamples: Xtr.length, testSamples: Xte.length }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    // GET /ml-model/artifact — latest saved model
    if (req.method === 'GET' && url.pathname.endsWith('/artifact')) {
      const { data, error } = await supabase
        .from('model_artifacts')
        .select('*')
        .order('trained_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (error || !data) {
        return new Response(JSON.stringify({ error: 'No trained model found' }), { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }
      return new Response(JSON.stringify(data), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    // POST /ml-model/predict — { features: {age, sex, cp, ...} }
    if (req.method === 'POST' && url.pathname.endsWith('/predict')) {
      const body = await req.json();
      const { data: artifact, error } = await supabase
        .from('model_artifacts')
        .select('*')
        .order('trained_at', { ascending: false })
        .limit(1)
        .maybeSingle();
      if (error || !artifact) {
        return new Response(JSON.stringify({ error: 'No trained model found — train the model first' }), { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
      }

      // Encode + impute: missing categorical/numeric -> dataset medians/modes
      const raw = FEATURE_NAMES.map(f => {
        const v = body.features?.[f];
        return Number.isFinite(Number(v)) && v !== null && v !== undefined && v !== '' ? Number(v) : null;
      });
      const colMedians = FEATURE_NAMES.map((_, c) => {
        const vals = DATASET.map(r => r[c]).filter(Number.isFinite);
        return median(vals);
      });
      const cleaned = raw.map((v, c) => v === null ? colMedians[c] : v);

      const means = artifact.means as number[];
      const stds = artifact.stds as number[];
      const w = artifact.weights as number[];
      const b = Number(artifact.bias);
      const z = b + cleaned.reduce((s, v, c) => s + ((v - means[c]) / stds[c]) * w[c], 0);
      const probability = sigmoid(z);

      return new Response(JSON.stringify({
        probability,
        prediction: probability >= 0.5 ? 1 : 0,
        modelVersion: artifact.version,
      }), { headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
    }

    return new Response(JSON.stringify({ error: 'Not found' }), { status: 404, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  } catch (err) {
    return new Response(JSON.stringify({ error: (err as Error).message }), { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } });
  }
});
